function isGitCommit(cmd) {
  const s = String(cmd);
  // 宽松兜底：cd x && git commit、sudo/sh -c 包裹、整体引号包裹等复合形式（误命中只会多跑门禁，方向安全）
  if (/\bgit\s+commit\b/.test(s)) return true;
  // 严格分词：识别 git -C <dir> commit 等全局选项变体
  const tokens = s.match(/"[^"]*"|'[^']*'|\S+/g) ?? [];
  if (tokens[0]?.replace(/^["']|["']$/g, "") !== "git") return false;
  for (let i = 1; i < tokens.length; i++) {
    const t = tokens[i].replace(/^["']|["']$/g, "");
    if (t === "commit") return true;
    if (GIT_GLOBAL_OPTS.has(t)) i++;
  }
  return false;
}

